-- Catlas sample data: 15 FICTIONAL places and fictional reviews.
-- Already loaded into the Supabase project. Run this only once (it would double the reviews).
-- Every place here has is_sample = true, which shows the "Sample listing" badge.
-- To remove all sample data later:  delete from public.places where is_sample;

insert into public.places
  (slug, name, address, neighborhood, lat, lng, hours, description, category, dog_policy, noise, setting,
   carrier_only, harness_ok, stroller_ok, water_bowl, quiet_corner, cat_savvy_staff, status, is_sample)
select v.*, 'approved', true from (values
  ('marmalade-and-mews-cafe', 'Marmalade & Mews Café', 'Sample address near Tremont St', 'South End', 42.3412, -71.0715, 'Daily 7am–4pm', 'A sunny corner café with window seats and a no-dogs rule, so nervous cats can relax over a (cat-safe) lap nap.', 'coffee', 'none', 'quiet', 'indoor', false, true, false, true, true, true),
  ('the-dog-eared-page', 'The Dog-Eared Page', 'Sample address near Centre St', 'Jamaica Plain', 42.3098, -71.1143, 'Tue–Sun 10am–7pm', 'Creaky floors, overstuffed armchairs, and a back reading nook. Dogs visit on weekends, but only in the front room.', 'bookstore', 'separated', 'quiet', 'indoor', false, true, true, true, true, false),
  ('purrcolator-roasters', 'Purrcolator Roasters', 'Sample address near Massachusetts Ave', 'Cambridge', 42.3655, -71.1039, 'Mon–Fri 6:30am–6pm, Sat–Sun 8am–5pm', 'A busy roastery with a calm back patio. Cats are welcome on the patio; the indoor counter gets loud at rush hour.', 'coffee', 'allowed', 'moderate', 'both', false, true, false, true, false, false),
  ('lantern-and-ladle-patio', 'Lantern & Ladle Patio', 'Sample address near Elm St', 'Somerville', 42.3967, -71.1226, 'Wed–Sun 11am–10pm (seasonal)', 'A string-lit patio restaurant with space between tables. Lively on weekend evenings, so we suggest weekday lunches for first-timers.', 'restaurant', 'allowed', 'lively', 'outdoor', false, true, false, true, false, false),
  ('whiskerwood-books', 'Whiskerwood Books', 'Sample address near Newbury St', 'Back Bay', 42.3503, -71.0812, 'Daily 10am–8pm', 'A hushed, wood-paneled shop with wide aisles and a resident book-stack cat sculpture. Staff love meeting visiting cats.', 'bookstore', 'none', 'quiet', 'indoor', false, true, true, false, true, true),
  ('tidewater-taproom', 'Tidewater Taproom', 'Sample address near Northern Ave', 'Seaport', 42.3519, -71.0421, 'Mon–Thu 3pm–10pm, Fri–Sun 12pm–11pm', 'Harbor-view taproom with a big roll-up door. Lively at night; carriers stay closed on a table or lap.', 'brewery', 'separated', 'lively', 'both', true, false, false, true, false, false),
  ('velvet-thimble-boutique', 'Velvet Thimble Boutique', 'Sample address near Charles St', 'Beacon Hill', 42.3588, -71.0707, 'Tue–Sat 11am–6pm', 'A tiny, tidy shop of scarves and notions. Hushed, with soft rugs and one very patient shopkeeper.', 'retail', 'none', 'quiet', 'indoor', false, true, false, false, false, true),
  ('thistle-hollow-garden', 'Thistle Hollow Garden', 'Sample address near Park Dr', 'Fenway', 42.3446, -71.1005, 'Dawn to dusk', 'A small public garden with shady benches and low hedges. Great for a harness stroll; dogs share the paths.', 'park', 'allowed', 'moderate', 'outdoor', false, true, true, true, false, false),
  ('saltbox-bakery-and-bagels', 'Saltbox Bakery & Bagels', 'Sample address near Hanover St', 'North End', 42.3647, -71.0542, 'Daily 6am–2pm', 'A cozy bakery with a few stools and a short line. Cats can ride along in their carriers while you pick up breakfast.', 'coffee', 'separated', 'moderate', 'indoor', true, false, false, false, false, false),
  ('copper-kettle-tea-room', 'Copper Kettle Tea Room', 'Sample address near Main St', 'Charlestown', 42.3782, -71.0602, 'Wed–Sun 10am–5pm', 'Quiet afternoon tea with a curtained corner booth that is purr-fect for shy cats. Staff are happy to bring a saucer of water.', 'other', 'none', 'quiet', 'indoor', false, true, false, true, true, true),
  ('paper-moth-stationery', 'Paper Moth Stationery', 'Sample address near Somerville Ave', 'Somerville', 42.3795, -71.0954, 'Thu–Mon 11am–6pm', 'A calm shop of notebooks and pens, with a wide front window cats love to watch. Strollers fit through the aisles.', 'retail', 'none', 'quiet', 'indoor', false, true, true, true, false, false),
  ('hopscotch-brewing-yard', 'Hopscotch Brewing Yard', 'Sample address near Dot Ave', 'Dorchester', 42.3, -71.0614, 'Wed–Sun 2pm–10pm', 'A big, fenced beer yard with picnic tables and games. Lots going on, so it''s best for confident, social cats.', 'brewery', 'allowed', 'lively', 'outdoor', false, true, false, true, false, false),
  ('juniper-and-wick-candle-shop', 'Juniper & Wick Candle Shop', 'Sample address near Broadway', 'South Boston', 42.338, -71.0462, 'Tue–Sun 10am–6pm', 'A fragrant little shop (strong scents, so sensitive noses beware). Cats stay in carriers, near the front.', 'retail', 'separated', 'moderate', 'indoor', true, false, false, false, false, false),
  ('rosebud-reading-room', 'Rosebud Reading Room', 'Sample address near Washington St', 'Roslindale', 42.287, -71.127, 'Daily 9am–6pm', 'A sleepy bookshop with a sunroom and a tiny back garden. Staff keep a quiet corner open for cats and their people.', 'bookstore', 'none', 'quiet', 'both', false, true, true, true, true, true),
  ('little-bell-community-garden', 'Little Bell Community Garden', 'Sample address near Chestnut Hill Ave', 'Brighton', 42.35, -71.1542, 'Dawn to dusk', 'A neighborhood garden with raised beds and a shady gravel path. Harness-friendly, with occasional dog traffic.', 'park', 'allowed', 'moderate', 'outdoor', false, true, false, false, false, false)
) as v(slug, name, address, neighborhood, lat, lng, hours, description, category, dog_policy, noise, setting,
       carrier_only, harness_ok, stroller_ok, water_bowl, quiet_corner, cat_savvy_staff)
on conflict (slug) do nothing;

